from bisect import bisect_right


def kthInRows(rows, k):
    lo = min(r[0] for r in rows)
    hi = max(r[-1] for r in rows)
    while lo < hi:
        mid = (lo + hi) // 2
        cnt = 0
        for r in rows:
            cnt += bisect_right(r, mid)
        if cnt >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
